static TychoArrK0 tycho_arr_K0_with_cap(Arena *a, tycho_int cap) {
    TychoArrK0 r; r.len = 0; r.cap = cap;
    r.data = cap > 0 ? (E_ast__Expr * *)arena_alloc(a, (size_t)cap * sizeof(E_ast__Expr *)) : 0;
    return r;
}
static void tycho_arr_K0_push(Arena *a, TychoArrK0 *xs, E_ast__Expr * v) {
    if (xs->len == xs->cap) {
        tycho_int nc = xs->cap ? xs->cap * 2 : 4;
        E_ast__Expr * *nd = (E_ast__Expr * *)arena_alloc(a, (size_t)nc * sizeof(E_ast__Expr *));
        for (tycho_int i = 0; i < xs->len; i++) nd[i] = xs->data[i];
        xs->data = nd; xs->cap = nc;
    }
    xs->data[xs->len++] = v;
}
static void tycho_arr_K0_grow(Arena *a, E_ast__Expr * **data, tycho_int *cap, tycho_int len) {
    tycho_int nc = *cap ? *cap * 2 : 4;
    E_ast__Expr * *nd = (E_ast__Expr * *)arena_alloc(a, (size_t)nc * sizeof(E_ast__Expr *));
    for (tycho_int i = 0; i < len; i++) nd[i] = (*data)[i];
    *data = nd; *cap = nc;
}
static void tycho_arr_K0_reserve(Arena *a, TychoArrK0 *xs, tycho_int n) {
    tycho_cap_check(n, sizeof(E_ast__Expr *));
    if (n <= xs->cap) return;
    E_ast__Expr * *nd = (E_ast__Expr * *)arena_alloc(a, (size_t)n * sizeof(E_ast__Expr *));
    for (tycho_int i = 0; i < xs->len; i++) nd[i] = xs->data[i];
    xs->data = nd; xs->cap = n;
}
